@Test
    @SneakyThrows
    public void test() {
        TwoFactorToken twoFactorToken = tokenManager.getToken("test", "test");

        Assert.assertTrue(twoFactorToken.expired());
        twoFactorToken.generate(1000L);
        Assert.assertFalse(twoFactorToken.expired());
        Thread.sleep(1100);
        Assert.assertTrue(twoFactorToken.expired());
    }

